/* Swift Penguin 73 by kamehame-ha — https://uiverse.io/kamehame-ha/swift-penguin-73 */
.badges {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  align-items: center;
  flex-wrap: wrap;
  justify-content: center;
}

.badges > button {
  font-size: 0.875rem;
  line-height: 1.25rem;
  padding: 2px .5rem;
  cursor: pointer;
  border: none;
  border-radius: 0.375rem;
  outline: none;
}

.badges .blue {
  background-color: rgba(59, 130, 246, 0.10);
  color: rgb(59 130 246);
  border: 1px rgb(59 130 246) solid;
}

.badges .yellow {
  background-color: rgba(234, 179, 8, 0.10);
  color: rgb(234 179 8);
  border: 1px rgb(234 179 8) solid;
}

.badges .green {
  background-color: rgba(34, 197, 94, 0.10);
  color: rgb(34 197 94);
  border: 1px rgb(34 197 94) solid;
}

.badges .red {
  background-color: rgba(239, 68, 68, 0.10);
  color: rgb(239 68 68);
  border: 1px rgb(239 68 68) solid;
}
